Task ID: java_permission_scope_trust_bug
Scenario: Service trusts orgId from request payload instead of the authenticated operator context.

Instructions:
Identify the highest-risk security bug and give the smallest maintainable fix. Prefer a clear trust-boundary correction over broad auth refactors.

Project snapshot:

=== File: src/main/java/com/example/report/ReportController.java ===
package com.example.report;

public class ReportController {
    private final ReportService reportService;

    public ReportController(ReportService reportService) {
        this.reportService = reportService;
    }

    public ReportDto generate(UserSession session, GenerateReportRequest request) {
        return reportService.generate(request.getOrgId(), session.getUserId(), request.getRange());
    }
}

=== File: src/main/java/com/example/report/GenerateReportRequest.java ===
package com.example.report;

public class GenerateReportRequest {
    private long orgId;
    private String range;

    public long getOrgId() {
        return orgId;
    }

    public String getRange() {
        return range;
    }
}

=== File: src/main/java/com/example/report/UserSession.java ===
package com.example.report;

public class UserSession {
    private long userId;
    private long orgId;

    public long getUserId() {
        return userId;
    }

    public long getOrgId() {
        return orgId;
    }
}
